package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"time"
)

var serviceSecret = os.Getenv("PIPELINE_HMAC_SECRET")

type PipelineTask struct {
	TaskID      string      `json:"task_id"`
	Repository  string      `json:"repository"`
	CommitSHA   string      `json:"commit_sha"`
	BuildSteps  []BuildStep `json:"build_steps"`
	Timestamp   int64       `json:"timestamp"`
	RequestedBy string      `json:"requested_by"`
}

type BuildStep struct {
	Name    string            `json:"name"`
	Image   string            `json:"image"`
	Command string            `json:"command"`
	Args    []string          `json:"args"`
	Env     map[string]string `json:"env"`
}

var commitSHARegex = regexp.MustCompile(`^[0-9a-f]{40}$`)
var taskIDRegex = regexp.MustCompile(`^[a-zA-Z0-9\-]{1,64}$`)

func computeHMAC(message []byte, secret string) string {
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(message)
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyHMAC(message []byte, signature string, secret string) bool {
	expected := computeHMAC(message, secret)
	return hmac.Equal([]byte(expected), []byte(signature))
}

func validateRepository(repo string) bool {
	allowedPrefixes := []string{"github.com/ourorg/", "gitlab.com/ourorg/"}
	for _, prefix := range allowedPrefixes {
		if strings.HasPrefix(repo, prefix) {
			return true
		}
	}
	return false
}

func validateBuildStep(step BuildStep) bool {
	allowedImages := map[string]bool{
		"golang:1.21":   true,
		"node:18":       true,
		"python:3.11":   true,
		"alpine:3.18":   true,
	}
	if !allowedImages[step.Image] {
		return false
	}
	allowedCommands := map[string]bool{
		"go build":   true,
		"go test":    true,
		"npm install": true,
		"npm test":   true,
		"pip install": true,
		"pytest":     true,
	}
	if !allowedCommands[step.Command] {
		return false
	}
	for _, arg := range step.Args {
		if strings.ContainsAny(arg, ";|&$`") {
			return false
		}
	}
	for k, v := range step.Env {
		if strings.ContainsAny(k+v, ";|&$`") {
			return false
		}
	}
	return true
}

func deserializeTask(data []byte) (*PipelineTask, error) {
	task := &PipelineTask{}
	if err := json.Unmarshal(data, task); err != nil {
		return nil, fmt.Errorf("deserialization failed: %w", err)
	}
	if !taskIDRegex.MatchString(task.TaskID) {
		return nil, fmt.Errorf("invalid task ID format")
	}
	if !commitSHARegex.MatchString(task.CommitSHA) {
		return nil, fmt.Errorf("invalid commit SHA format")
	}
	if len(task.BuildSteps) == 0 || len(task.BuildSteps) > 10 {
		return nil, fmt.Errorf("invalid number of build steps")
	}
	return task, nil
}

func executePipeline(task *PipelineTask) error {
	for _, step := range task.BuildSteps {
		if !validateBuildStep(step) {
			return fmt.Errorf("invalid build step: %s", step.Name)
		}
		args := []string{"run", "--rm", "--network=none", "--read-only", step.Image, step.Command}
		args = append(args, step.Args...)
		cmd := exec.Command("docker", args...)
		cmd.Env = []string{}
		for k, v := range step.Env {
			cmd.Env = append(cmd.Env, fmt.Sprintf("%s=%s", k, v))
		}
		if output, err := cmd.CombinedOutput(); err != nil {
			return fmt.Errorf("step %s failed: %s - %w", step.Name, string(output), err)
		}
	}
	return nil
}

func handlePipelineTrigger(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	signature := r.Header.Get("X-Pipeline-Signature")
	if signature == "" {
		http.Error(w, "missing signature", http.StatusUnauthorized)
		return
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		http.Error(w, "read error", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	if !verifyHMAC(body, signature, serviceSecret) {
		http.Error(w, "invalid signature", http.StatusForbidden)
		return
	}

	task, err := deserializeTask(body)
	if err != nil {
		http.Error(w, "invalid task", http.StatusBadRequest)
		return
	}

	if !validateRepository(task.Repository) {
		http.Error(w, "unauthorized repository", http.StatusForbidden)
		return
	}

	if time.Now().Unix()-task.Timestamp > 300 {
		http.Error(w, "request expired", http.StatusBadRequest)
		return
	}

	log.Printf("Executing pipeline %s for %s", task.TaskID, task.Repository)
	if err := executePipeline(task); err != nil {
		http.Error(w, "pipeline execution failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "pipeline %s completed", task.TaskID)
}

func main() {
	if serviceSecret == "" {
		log.Fatal("PIPELINE_HMAC_SECRET must be set")
	}
	if len(serviceSecret) < 32 {
		log.Fatal("PIPELINE_HMAC_SECRET must be at least 32 characters")
	}
	http.HandleFunc("/api/v1/pipeline/trigger", handlePipelineTrigger)
	log.Println("Pipeline executor listening on :8443")
	log.Fatal(http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil))
}
